def slugify(text: str) -> str:
    if not isinstance(text, str):
        return ""

    words = []
    current = []

    for ch in text:
        if ch.isalpha() or ch.isdigit():
            current.append(ch)
        elif current:
            words.append("".join(current).lower())
            current = []

    if current:
        words.append("".join(current).lower())

    if not words:
        return ""

    result = "-".join(words)
    if len(result) <= 60:
        return result

    selected = []
    length = 0

    for word in words:
        addition = len(word) + (1 if selected else 0)
        if length + addition <= 60:
            selected.append(word)
            length += addition
        else:
            if not selected:
                return result[:60]
            break

    return "-".join(selected)

