def chunked(items, size):
    if isinstance(size, bool) or not isinstance(size, int):
        raise ValueError("size must be an integer")
    if size <= 0:
        raise ValueError("size must be positive")

    iterator = iter(items)
    result = []

    while True:
        chunk = list(islice(iterator, size))
        if not chunk:
            break
        result.append(chunk)

    return result

